const V8_FIRE = [0, 0.125, 0.25, 0.375, 0.5, 0.625, 0.75, 0.875];
const V8_BANK = [0, 0, 1, 0, 1, 1, 0, 1];

const PROFILES = [
  { // 0: v8muscle  (Mustang Mach 1, 4.6 DOHC, dual exhaust, lumpy cams)
    fire: V8_FIRE, bank: V8_BANK, bankDelay: 0.00095, bankAmp: 0.84,
    pulseA: 1.0, pulseW: 0.46, maxW: 0.011, noise: 0.3, nDec: 0.0017,
    body: 0.35, bodyF: 150, bDec: 0.006,
    tJit: 0.09, aJit: 0.16, lope: 0.95, hunt: 0.035, crackP: 0.5, popA: 1.6,
    pipe1: 0.0072, g1: -0.45, damp1: 0.38, pipe2: 0.0023, g2: -0.3, damp2: 0.6,
    intake: 0.45, tick: 0.0, tickPos: [], rattle: 0.06, rattleRpm: 2600, buzz: 0,
    mech: 0.35, out: 0.55,
  },
  { // 1: v8truck  (F-150 1998, 4.6 SOHC, single exhaust, tired lifters, rattly)
    fire: V8_FIRE, bank: V8_BANK, bankDelay: 0.00035, bankAmp: 0.94,
    pulseA: 1.0, pulseW: 0.62, maxW: 0.014, noise: 0.22, nDec: 0.0022,
    body: 0.5, bodyF: 92, bDec: 0.011,
    tJit: 0.07, aJit: 0.2, lope: 0.3, hunt: 0.018, crackP: 0.12, popA: 0.95,
    pipe1: 0.0105, g1: -0.55, damp1: 0.45, pipe2: 0.0034, g2: -0.35, damp2: 0.5,
    intake: 0.2, tick: 0.6, tickPos: [0.17, 0.59], rattle: 0.55, rattleRpm: 1900, buzz: 0,
    mech: 0.5, out: 0.55,
  },
  { // 2: single4t  (Honda Big Red 250, air-cooled thumper, plastic everywhere)
    fire: [0], bank: [0], bankDelay: 0, bankAmp: 1,
    pulseA: 1.0, pulseW: 0.085, maxW: 0.009, noise: 0.5, nDec: 0.0032,
    body: 0.85, bodyF: 108, bDec: 0.017,
    tJit: 0.02, aJit: 0.16, lope: 0.25, hunt: 0.02, crackP: 0.55, popA: 1.15,
    pipe1: 0.0036, g1: -0.5, damp1: 0.32, pipe2: 0.0011, g2: -0.42, damp2: 0.42,
    intake: 0.28, tick: 0.3, tickPos: [0.4], rattle: 0.35, rattleRpm: 5200, buzz: 0.9,
    mech: 0.55, out: 0.62,
  },
];

const NPULSE = 10;
const DLEN = 4096;
const DMASK = DLEN - 1;

class BebiEngine extends AudioWorkletProcessor {
  static get parameterDescriptors() {
    return [
      { name: 'rpm', defaultValue: 800, minValue: 0, maxValue: 30000, automationRate: 'k-rate' },
      { name: 'throttle', defaultValue: 0, minValue: 0, maxValue: 1, automationRate: 'k-rate' },
      { name: 'load', defaultValue: 0, minValue: 0, maxValue: 2, automationRate: 'k-rate' },
      { name: 'crackle', defaultValue: 0, minValue: 0, maxValue: 1, automationRate: 'k-rate' },
      { name: 'rough', defaultValue: 0, minValue: 0, maxValue: 1, automationRate: 'k-rate' },
      { name: 'active', defaultValue: 1, minValue: 0, maxValue: 1, automationRate: 'k-rate' },
    ];
  }

  constructor(options) {
    super(options);
    const o = (options && options.processorOptions) || {};
    this.seed = ((o.seed || 12345) >>> 0) || 1;
    this.pulses = [];
    for (let i = 0; i < NPULSE; i++) this.pulses.push({ on: false, t: 0, A: 0, W: 1, invW: 1, nA: 0, nE: 0, nD: 0, rA: 0, rE: 0, rD: 0, rPh: 0, rInc: 0 });
    this.evPos = new Float32Array(9);
    this.evAmp = new Float32Array(9);
    this.nEv = 0; this.evIdx = 0; this.tickIdx = 0;
    this.cyc = 0; this.rpmS = 800; this.huntPh = 0; this.huntF = 0;
    this.d1 = new Float32Array(DLEN); this.d2 = new Float32Array(DLEN); this.w = 0; this.lp1 = 0; this.lp2 = 0;
    this.dcX = 0; this.dcY = 0;
    this.envF = 0; this.tickE = 0; this.rattE = 0; this.buzz = 0;
    this.popQ = 0;
    this.tickDec = Math.exp(-1 / (0.00045 * sampleRate));
    this.rattDec = Math.exp(-1 / (0.0013 * sampleRate));
    this.buzzDec = Math.exp(-1 / (0.011 * sampleRate));
    this.config(o.type | 0, o.idle || 800, o.redline || 6500);
    this.port.onmessage = (e) => {
      const d = e.data || {};
      if (d.cfg) this.config(d.cfg.type | 0, d.cfg.idle, d.cfg.redline);
      if (d.pop) this.popQ = Math.min(4, this.popQ + d.pop);
    };
  }

  config(type, idle, red) {
    this.P = PROFILES[Math.max(0, Math.min(PROFILES.length - 1, type))];
    this.idle = idle || 800;
    this.red = red || 6500;
    this.rpmS = this.idle;
    this.D1 = Math.min(DLEN - 2, Math.max(8, Math.round(this.P.pipe1 * sampleRate)));
    this.D2 = Math.min(DLEN - 2, Math.max(4, Math.round(this.P.pipe2 * sampleRate)));
    this.d1.fill(0); this.d2.fill(0); this.lp1 = 0; this.lp2 = 0;
    for (let i = 0; i < NPULSE; i++) this.pulses[i].on = false;
    this.cyc = 0;
    this.plan();
  }

  rnd() {
    let x = this.seed;
    x ^= x << 13; x ^= x >>> 17; x ^= x << 5;
    x >>>= 0;
    this.seed = x;
    return x / 4294967296;
  }

  idleness() {
    const v = 1 - (this.rpmS - this.idle) / (this.idle * 1.4);
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  /** plan the firing events of the next 720 deg cycle (lope + jitter) */
  plan() {
    const P = this.P;
    const n = P.fire.length;
    const cycHz = Math.max(1, this.rpmS / 120);
    const idl = this.idleness();
    for (let k = 0; k < n; k++) {
      let pos = P.fire[k];
      if (P.bank[k]) pos += Math.min(0.4 / n, P.bankDelay * cycHz);
      pos += ((this.rnd() - 0.5) * P.tJit * (0.3 + idl)) / n;
      let a = 1 + (this.rnd() - 0.5) * 2 * P.aJit * (0.35 + 0.65 * idl);
      if (P.bank[k]) a *= P.bankAmp;
      if (idl > 0.25 && this.rnd() < P.lope * idl * 0.3) a *= 0.3 + 0.35 * this.rnd();
      this.evPos[k] = pos < 0 ? 0 : pos > 0.9999 ? 0.9999 : pos;
      this.evAmp[k] = a;
    }
    for (let i = 1; i < n; i++) {
      let j = i;
      while (j > 0 && this.evPos[j - 1] > this.evPos[j]) {
        const tp = this.evPos[j]; this.evPos[j] = this.evPos[j - 1]; this.evPos[j - 1] = tp;
        const ta = this.evAmp[j]; this.evAmp[j] = this.evAmp[j - 1]; this.evAmp[j - 1] = ta;
        j--;
      }
    }
    this.nEv = n;
    this.evIdx = 0;
    this.tickIdx = 0;
  }

  slot() {
    let best = this.pulses[0];
    for (let i = 0; i < NPULSE; i++) {
      const p = this.pulses[i];
      if (!p.on) return p;
      if (p.t > best.t) best = p;
    }
    return best;
  }

  fire(k, load, crackle) {
    const P = this.P;
    const n = this.nEv;
    const cycHz = Math.max(0.5, this.rpmS / 120);
    const Ti = sampleRate / (cycHz * n);
    const L = load > 1.3 ? 1.3 : load;
    let a = this.evAmp[k] * (0.2 + 0.8 * L);
    let nMul = 0.35 + 0.9 * L;
    let W = P.pulseW * Ti * (1 - 0.3 * (L > 1 ? 1 : L));
    const maxW = P.maxW * sampleRate;
    if (W > maxW) W = maxW;
    if (W < 6) W = 6;
    let pop = 0;
    const over = load < 0.2 && this.rpmS > this.idle * 1.8;
    if (over) { a *= 0.6; nMul *= 1.3; }
    if (crackle > 0 && over && this.rnd() < crackle * P.crackP) pop = 1;
    if (this.popQ > 0) { pop = 1 + this.popQ; this.popQ = 0; }
    if (pop) {
      a = (0.9 + 0.5 * this.rnd()) * (1 + pop * 0.5) * P.popA;
      nMul = 3 + pop;
      W = Math.max(6, W * 0.5);
    }
    const p = this.slot();
    p.on = true;
    p.t = 0;
    p.A = a * P.pulseA;
    p.W = W;
    p.invW = 1 / W;
    p.nA = a * P.noise * nMul;
    p.nE = 1;
    p.nD = Math.exp(-1 / (P.nDec * (pop ? 3 : 1) * sampleRate));
    p.rA = a * P.body * (pop ? 1.5 : 1);
    p.rE = 1;
    p.rD = Math.exp(-1 / (P.bDec * sampleRate));
    p.rPh = 0;
    p.rInc = (P.bodyF * (1 + 0.08 * (this.rnd() - 0.5))) / sampleRate;
    if (P.buzz > 0) this.buzz = 1;
  }

  process(inputs, outputs, params) {
    const out = outputs[0];
    const L = out[0];
    const R = out.length > 1 ? out[1] : null;
    const N = L.length;
    if (params.active[0] < 0.5) {
      L.fill(0);
      if (R) R.fill(0);
      return true;
    }
    const P = this.P;
    const rpmT = params.rpm[0];
    const load = params.load[0];
    const thr = params.throttle[0];
    const crackle = params.crackle[0];
    const rough = params.rough[0];
    // per-block: idle hunting (lopey idle)
    const idl = this.idleness();
    this.huntPh += (TWO_PI * 0.85 * N) / sampleRate;
    if (this.huntPh > TWO_PI) { this.huntPh -= TWO_PI; this.huntF = (this.rnd() - 0.5) * 0.6; }
    const hunt = 1 + P.hunt * idl * (Math.sin(this.huntPh) + this.huntF);
    const rpmFrac = Math.max(0, Math.min(1, (this.rpmS - this.idle) / Math.max(1, this.red - this.idle)));
    const vib = Math.exp(-Math.pow((this.rpmS - P.rattleRpm) / (0.22 * P.rattleRpm), 2));
    const rattRate = (P.rattle * (rough * 90 + vib * 35)) / sampleRate;
    const buzzRate = (P.buzz * 1800) / sampleRate;
    const tickAmp = P.tick * (1 - 0.6 * rpmFrac);
    const intake = P.intake * (0.2 + 0.8 * thr);
    const nTick = P.tickPos.length;
    const rpmK = 1 - Math.exp(-1 / (0.012 * sampleRate));
    for (let i = 0; i < N; i++) {
      this.rpmS += (rpmT - this.rpmS) * rpmK;
      const cycHz = (this.rpmS * hunt) / 120;
      this.cyc += cycHz / sampleRate;
      if (this.cyc >= 1) {
        this.cyc -= 1;
        if (this.cyc >= 1) this.cyc = 0;
        this.plan();
      }
      while (this.evIdx < this.nEv && this.cyc >= this.evPos[this.evIdx]) {
        this.fire(this.evIdx, load, crackle);
        this.evIdx++;
      }
      if (this.tickIdx < nTick && this.cyc >= P.tickPos[this.tickIdx]) {
        this.tickE = tickAmp * (0.55 + 0.45 * this.rnd()) * (this.tickIdx === 0 ? 1 : 0.6);
        this.tickIdx++;
      }
      // exhaust pulses
      let x = 0;
      for (let j = 0; j < NPULSE; j++) {
        const p = this.pulses[j];
        if (!p.on) continue;
        let v = 0;
        if (p.t < p.W) v += p.A * hsin(p.t * p.invW);
        v += p.nA * p.nE * (this.rnd() * 2 - 1);
        p.nE *= p.nD;
        if (p.rA > 0) {
          v += p.rA * p.rE * sinC(p.rPh);
          p.rPh += p.rInc;
          if (p.rPh >= 1) p.rPh -= 1;
          p.rE *= p.rD;
        }
        p.t++;
        if (p.t >= p.W && p.nE < 0.0004 && p.rE < 0.0004) p.on = false;
        x += v;
      }
      // DC blocker
      const dx = x - this.dcX + 0.995 * this.dcY;
      this.dcX = x;
      this.dcY = dx;
      // header + tail pipe waveguides (negative reflection at open ends, damped)
      const r1 = this.d1[(this.w - this.D1) & DMASK];
      this.lp1 += (r1 - this.lp1) * P.damp1;
      const y1 = dx + P.g1 * this.lp1;
      this.d1[this.w] = y1;
      const r2 = this.d2[(this.w - this.D2) & DMASK];
      this.lp2 += (r2 - this.lp2) * P.damp2;
      const y2 = y1 + P.g2 * this.lp2;
      this.d2[this.w] = y2;
      this.w = (this.w + 1) & DMASK;
      L[i] = y2 * P.out;
      if (R) {
        const ax = x < 0 ? -x : x;
        this.envF += (ax - this.envF) * 0.02;
        let m = (this.rnd() * 2 - 1) * (0.1 + this.envF * 1.8) * intake;
        if (this.tickE > 0.0005) { m += (this.rnd() * 2 - 1) * this.tickE; this.tickE *= this.tickDec; }
        if (this.buzz > 0.001) this.buzz *= this.buzzDec;
        if (this.rnd() < rattRate + this.buzz * buzzRate) {
          const nr = 0.3 + 0.7 * this.rnd();
          if (nr > this.rattE) this.rattE = nr;
        }
        if (this.rattE > 0.0005) { m += (this.rnd() * 2 - 1) * this.rattE * 0.6; this.rattE *= this.rattDec; }
        R[i] = m * P.mech;
      }
    }
    return true;
  }
}

registerProcessor('bebi-engine', BebiEngine);
